    private static final Map<String, MaskSpec> SPEC_BY_KEY;

    static {
        HashMap<String, MaskSpec> m = new HashMap<>();
        m.put("circle", new MaskSpec(CIRCLE_PATH));
        m.put("square", new MaskSpec(SQUARE_PATH));
        m.put("four_sided_cookie", new MaskSpec(FOUR_SIDED_COOKIE_PATH));
        m.put("seven_sided_cookie", new MaskSpec(SEVEN_SIDED_COOKIE_PATH));
        m.put("arch", new MaskSpec(ARCH_PATH));
        m.put("ios_rounded_square", new MaskSpec(IOS_ROUNDED_SQUARE_PATH));
        m.put("meow", new MaskSpec(MEOW_PATH));
        m.put("flower", new MaskSpec(FLOWER_PATH));
        m.put("heart", new MaskSpec(HEART_PATH));
        m.put("hexagon", new MaskSpec(HEXAGON_PATH));
        m.put("leaf", new MaskSpec(LEAF_PATH));
        m.put("cloudy", new MaskSpec(CLOUDY_PATH));
        m.put("cylindrical", new MaskSpec(CYLINDRICAL_PATH));
        m.put("stretched", new MaskSpec(STRETCHED_PATH));
        m.put("pebble", new MaskSpec(PEBBLE_PATH));
        m.put("rice_balls", new MaskSpec(RICE_BALLS_PATH));
        m.put("rounded_rect", new MaskSpec(ROUNDED_RECT_PATH));
        m.put("squircle", new MaskSpec(SQUIRCLE_PATH));
        m.put("tapered_rect", new MaskSpec(TAPERED_RECT_PATH));
        m.put("teardrop", new MaskSpec(TEARDROP_PATH));
        m.put("vessel", new MaskSpec(VESSEL_PATH));
        m.put("rounded_hexagon", new MaskSpec(ROUNDED_HEXAGON_PATH));
        m.put("just_icons", new MaskSpec(JUST_ICONS_CLIP_PATH));
        m.put("dotted_circle", new MaskSpec(CIRCLE_PATH));
        m.put("outline_style", new MaskSpec(CIRCLE_PATH));
        m.put("solid_circle_ring", new MaskSpec(CIRCLE_PATH)); // legacy; same as outline_style
        m.put("squaremedo", new MaskSpec(IOS_ROUNDED_SQUARE_PATH));
        SPEC_BY_KEY = Collections.unmodifiableMap(m);
    }

    private QsTileIconShapePathData() {}

    static String pathStringForKey(String key) {
        MaskSpec s = SPEC_BY_KEY.get(key);
        return s != null ? s.path : SPEC_BY_KEY.get(DEFAULT_KEY).path;
    }

    static float viewBoxForKey(String key) {
        MaskSpec s = SPEC_BY_KEY.get(key);
        return s != null ? s.viewBox : SPEC_BY_KEY.get(DEFAULT_KEY).viewBox;
    }

    static boolean isKnownKey(String key) {
        return key != null && SPEC_BY_KEY.containsKey(key);
    }

    /** ViewBox for dotted-circle ornament path (matches SystemUI). */
    static final float DOTTED_ORNAMENT_VIEW_BOX = 48f;

    /** Matches SystemUI classicOrnamentStrokeWidthFraction for outline_style. */
    static final float PREVIEW_OUTLINE_STROKE_FRACTION = 0.022f;

    /** Path for list preview; dotted / squaremedo use ornament artwork, not the filled mask. */
    static String pathDataForPreview(String shapeKey) {
        if ("dotted_circle".equals(shapeKey)) {
            return DOTTED_CIRCLE_ORNAMENT_PATH;
        }
        if ("squaremedo".equals(shapeKey)) {
            return SQUAREMEDO_ORNAMENT_PATH;
        }
        return pathStringForKey(shapeKey);
    }

    static float viewBoxForPreview(String shapeKey) {
        if ("dotted_circle".equals(shapeKey) || "squaremedo".equals(shapeKey)) {
            return DOTTED_ORNAMENT_VIEW_BOX;
        }
        return viewBoxForKey(shapeKey);
    }

    /** Non-zero means stroke-only preview (outline ring). */
    static float previewStrokeFractionFor(String shapeKey) {
        if ("outline_style".equals(shapeKey) || "solid_circle_ring".equals(shapeKey)) {
            return PREVIEW_OUTLINE_STROKE_FRACTION;
        }
        return 0f;
    }
